// ESP32 — MPU-6050 Lage erkennen
#include <Adafruit_MPU6050.h>
#include <Adafruit_Sensor.h>
#include <Wire.h>

Adafruit_MPU6050 mpu;

void setup() {
  Serial.begin(115200);
  if (!mpu.begin()) {
    Serial.println("MPU-6050 nicht gefunden!");
    while (true) delay(10);
  }
  mpu.setAccelerometerRange(MPU6050_RANGE_8_G);
  Serial.println("MPU-6050 bereit.");
}

void loop() {
  sensors_event_t a, g, temp;
  mpu.getEvent(&a, &g, &temp);

  Serial.print("X: "); Serial.print(a.acceleration.x);
  Serial.print("  Y: "); Serial.print(a.acceleration.y);
  Serial.print("  Z: "); Serial.println(a.acceleration.z);

  if (a.acceleration.x > 5) {
    Serial.println(" → nach rechts gekippt");
  } else if (a.acceleration.x < -5) {
    Serial.println(" → nach links gekippt");
  } else if (a.acceleration.z < 5) {
    Serial.println(" → senkrecht gestellt");
  } else {
    Serial.println(" → liegt flach");
  }

  delay(500);
}
